"""Table tests generated by code across the whole defect vocabulary, through the real loader and database."""
from __future__ import annotations

import itertools

import pytest

import make_sample_xer as gen
from conftest import TENANT, snapshot
from xerlane.load import load_file
from xerlane.reconcile import reconcile

pytestmark = pytest.mark.db

KINDS = sorted(gen.DEFECTS)
FATAL = sorted(k for k, v in gen.DEFECTS.items() if v[2])
ROW_LEVEL = sorted(k for k, v in gen.DEFECTS.items() if not v[2])


def reported_codes(result):
    return {f.rule for f in result.findings if f.severity == "error"} | {q.code for q in result.quarantined}


@pytest.mark.parametrize("kind", ROW_LEVEL)
@pytest.mark.parametrize("seed", [1, 2])
def test_row_level_defect_is_quarantined_named_and_reconciles(conn, xer, kind, seed):
    path, planted = xer(seed=seed, tasks=120, defects=[kind])
    r = load_file(conn, TENANT, path)
    assert r.status == "loaded" and r.exit_code == 1, "loaded, but not silently: exit code 1 says rows were set aside"
    assert set(planted[0].expect) <= reported_codes(r), f"{kind}: {sorted(reported_codes(r))}"
    assert r.quarantined or kind == "stray_line", "a defect must leave a quarantined row (a stray line has no row of its own)"
    rec = reconcile(conn, TENANT, path)
    assert rec.ok, [str(f) for f in rec.findings]


@pytest.mark.parametrize("kind", FATAL)
def test_file_level_defect_rejects_the_whole_file(conn, xer, admin, kind):
    path, planted = xer(seed=1, tasks=120, defects=[kind])
    r = load_file(conn, TENANT, path)
    assert r.status == "rejected" and r.exit_code == 2 and "MISSING_END" in {f.rule for f in r.findings}
    assert admin.execute("select (select count(*) from task) + (select count(*) from quarantine) + (select count(*) from load_run)").fetchone()[0] == 0


@pytest.mark.parametrize("kind", ROW_LEVEL)
def test_no_row_is_lost_every_file_row_is_stored_or_quarantined(conn, xer, kind):
    path, _ = xer(seed=5, tasks=100, defects=[kind])
    r = load_file(conn, TENANT, path)
    rec = reconcile(conn, TENANT, path)
    for line in rec.lines:
        assert line.file_rows == line.stored + line.quarantined, line
    # and the loader's own account agrees with the independent one
    total_quarantined = sum(line.quarantined for line in rec.lines)
    assert total_quarantined == len(r.quarantined)


@pytest.mark.parametrize("a,b", [p for p in itertools.combinations(ROW_LEVEL, 2)])
def test_pairs_of_defects_are_both_accounted_for(conn, xer, a, b):
    path, planted = xer(seed=7, tasks=150, defects=[a, b])
    r = load_file(conn, TENANT, path)
    assert r.status == "loaded" and r.quarantined
    assert reconcile(conn, TENANT, path).ok
    for p in planted:
        if p.table and p.key:
            # either its own code is reported, or the planted row was set aside because another defect took it out first
            line_codes = {q.code for q in r.quarantined if q.line == p.line} | ({"STRAY"} if p.kind == "stray_line" else set())
            assert set(p.expect) <= reported_codes(r) or line_codes, (a, b, p)


def test_all_defects_at_once_still_load_the_rest_and_reconcile(conn, xer):
    path, _ = xer(seed=3, tasks=200, defects=ROW_LEVEL)
    r = load_file(conn, TENANT, path)
    assert r.status == "loaded" and len(r.quarantined) >= len(ROW_LEVEL) - 1
    assert reconcile(conn, TENANT, path).ok


def test_loading_a_defective_file_then_its_fixed_version_leaves_the_fixed_state(conn, xer, admin):
    bad, _ = xer(seed=8, tasks=100, defects=ROW_LEVEL, name="v.xer")
    good, _ = xer(seed=8, tasks=100, name="v.xer")
    load_file(conn, TENANT, bad)
    load_file(conn, TENANT, good)
    fresh = snapshot(admin, TENANT)
    admin.execute("truncate xerlane.quarantine, xerlane.change_event, xerlane.load_run, xerlane.taskrsrc, xerlane.taskpred, xerlane.task, xerlane.projwbs, xerlane.project, xerlane.rsrc, xerlane.calendar")
    load_file(conn, TENANT, good)
    assert snapshot(admin, TENANT) == fresh


def test_every_defect_kind_has_a_description_a_code_and_a_test():
    assert set(gen.DEFECTS) == set(ROW_LEVEL) | set(FATAL)
    for kind, (text, expect, fatal) in gen.DEFECTS.items():
        assert text and expect and all(c.isupper() or c == "_" for c in "".join(expect)), kind
